#define main legacy_main
#include "../shuffle-cuda/main.cu"
#undef main
#include <vector>
#include <cstring>
#include <string>
#include <cstdint>
constexpr int N=8192;
struct Path{int kind,sg,input;int32_t arg;int*oi;float*of;Path(int k,int s,int32_t a,int fixture):kind(k),sg(s),input(fixture),arg(a),oi(nullptr),of(nullptr){if(kind<=2)cudaMalloc(&oi,256*4);else cudaMalloc(&of,N*4);}void launch(float*in){if(kind==1){if(sg==8)bcast_shfl_xor_sg8<<<1,256>>>(oi);else if(sg==16)bcast_shfl_xor_sg16<<<1,256>>>(oi);else bcast_shfl_xor_sg32<<<1,256>>>(oi);}else if(kind==2){if(sg==8)bcast_shfl_sg8<<<1,256>>>(arg,oi);else if(sg==16)bcast_shfl_sg16<<<1,256>>>(arg,oi);else bcast_shfl_sg32<<<1,256>>>(arg,oi);}else transpose_shfl<<<N/sg,sg>>>(of,in);}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;std::vector<float>input[2];for(int i=0;i<N;i++){input[0].push_back(float(i)*10.f);input[1].push_back(i%257==0?-0.f:float((i*13)%16381-8190)/16.f);}float*din[2];for(int j=0;j<2;j++){cudaMalloc(&din[j],N*4);cudaMemcpy(din[j],input[j].data(),N*4,cudaMemcpyHostToDevice);}uint32_t bits[2]={0xdeadbeefu,123456789u};int32_t patterns[2];memcpy(patterns,bits,8);std::vector<Path>paths;for(int s:{8,16,32})paths.emplace_back(1,s,0,0);for(int32_t arg:patterns)for(int s:{8,16,32})paths.emplace_back(2,s,arg,0);for(int j=0;j<2;j++)for(int s:{8,16,32})paths.emplace_back(3,s,0,j);std::vector<double>prefix{N,256,double(patterns[0]),double(patterns[1]),8,16,32};for(auto&in:input)prefix.insert(prefix.end(),in.begin(),in.end());for(auto&p:paths)p.launch(din[p.input]);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){std::vector<double>times;for(auto&p:paths){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)p.launch(din[p.input]);cudaDeviceSynchronize();times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep);}std::vector<double>got;bool ok=cudaGetLastError()==cudaSuccess;for(auto&p:paths){if(p.kind<=2){std::vector<int32_t>a(256);cudaMemcpy(a.data(),p.oi,256*4,cudaMemcpyDeviceToHost);int expected=p.kind==1?p.sg*(p.sg-1)/2:p.arg;for(auto v:a){ok&=v==expected;got.push_back(v);}}else{std::vector<float>a(N),gold(N),sourcegold(N);cudaMemcpy(a.data(),p.of,N*4,cudaMemcpyDeviceToHost);for(int base=0;base<N;base+=p.sg)for(int j=0;j<p.sg;j++)gold[base+j]=input[p.input][base+p.sg-j-1];matrixTransposeCPUReference(sourcegold.data(),input[p.input].data(),N/p.sg,p.sg);ok&=memcmp(a.data(),gold.data(),N*4)==0&&memcmp(a.data(),sourcegold.data(),N*4)==0;got.insert(got.end(),a.begin(),a.end());}}double elapsed=0;for(auto t:times)elapsed+=t;auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string file=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(file.c_str(),"wb");fwrite(art.data(),8,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"sum15paths_XOR_broadcast_blockreverse_kernelonly\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[",trial,elapsed,ok?"true":"false",got.size(),rep);for(size_t i=0;i<times.size();i++)printf(i?",%.17g":"%.17g",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file.c_str(),art.size());if(!ok)return 2;}for(auto&p:paths)if(p.kind<=2)cudaFree(p.oi);else cudaFree(p.of);for(auto ptr:din)cudaFree(ptr);}
